head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = 'ULDBNS25000.xml';
scwin.vIsurCd, scwin.vIsurNm;
scwin.vCorpYn = '';
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.arrPar = new Array();
scwin.processGp; //수정 4
scwin.btnStat = new Object();
scwin.vChgYn = 'N';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};


/********************************************** 
 * 함수명  	 : fn_SearchIsur
 * 설명       : 발행기관 리스트를 조회 한다.
 ***********************************************/
scwin.fn_SearchIsur = function() {
    scwin.vIsurNm = $c.stf.getObjectValue(txb_IsurCd);
    var dsNm = 'BNS_ISUR_INFO';
    var qryId = 'lds.stf.bnslistsrchl.select.listIsurCd';
    var param = '&{P}V_ISUR_NM=' + scwin.vIsurNm;
    param += '&{P}V_BND_LIST_CORP_YN=' + scwin.vCorpYn;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_IsurList, dsNm, qryId, param);
    $c.cm.ShowWin(grd_IsurList);
};


/********************************************** 
 * 함수명  	 : fn_SearchIsurDtl
 * 설명       : 발행기관 상세 조회
 ***********************************************/
scwin.fn_SearchIsurDtl = function() {
    var dsNm = 'BNS_ISUR_DTL_INFO';
    var qryId = 'lds.stf.bnslistsrchl.select.readIsurCd';
    var param = '&{P}V_ISUR_CD=' + scwin.vIsurCd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_DtlInfo, dsNm, qryId, param);
};


/********************************************** 
 * 함수명    : fn_SelectBdchrgList
 * 설명       : 신고담당자 목록 조회
 ***********************************************/
scwin.fn_SelectBdchrgList = function() {
    if (grd_IsurList.getFocusedRowIndex() < 1) return;
    var dsNm = 'BNS_BND_DECL_CHRG_LIST';
    var qryId = 'lds.stf.bnsdecl_mgr.select.selectBndDeclChrgList';
    var param = '&{P}V_ISUR_CD=' + scwin.vIsurCd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_BdchrgList, dsNm, qryId, param);
};


/********************************************** 
 * 함수명  	 : fn_ComChgList
 * 설명       : 회사명 변경 내역을 조회 한다.
 ***********************************************/
scwin.fn_ComChgList = function() {
    var dsNm = 'BNS_COM_CHG_LIST';
    var qryId = 'lds.stf.bnslistsrchl.select.listChgComNm';
    var param = '&{P}V_ISUR_CD=' + scwin.vIsurCd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_ComChgList, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_InputCheck
 * 설명      : 필수 입력 값을 체크한다. 
 ***********************************************/
scwin.fn_InputCheck = function() {
    //자리수 체크
    if (!$c.stf.checkMaxLength(txb_ChrgNm, 80, '이름')) return false;
    if (!$c.stf.checkMaxLength(txb_ChrgEmail1, 30, '이메일 계정')) return false;
    if (!$c.stf.checkMaxLength(txb_ChrgEmail2, 70, '이메일 주소')) return false;
    return true;
};


/********************************************** 
 * 함수명   : fn_Mod
 * 설명       : 담당자 정보를 수정한다.
 ***********************************************/
scwin.fn_Mod = function() {
    if (scwin.vIsurCd == '') {
        $c.win.alert('발행기관을 선택 하십시오.');
        return;
    }

    /**
     * 필수입력값 체크 
     * TOBE 패스워드 항목 삭제로 체크안함
     */
    if (scwin.fn_InputCheck() == false) return;
    if (scwin.vChgYn == 'N') {
        $c.win.alert('변경된 담당자 정보가 없습니다.');
        return;
    }
    if (!confirm("담당자 정보를 수정하시겠습니까?")) return;
    var url = "/bns/ListSrchl.do?method=updateChrgInfo";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_DtlInfo)";
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_clearPwd
 * 설명       : 사용자아이디 잠금해제
 ***********************************************/
scwin.fn_clearPwd = function() {
    //alert(vIsurCd);
    if (scwin.vIsurCd == '') {
        $c.win.alert('발행기관을 선택 하십시오.');
        return;
    }
    if (!confirm("비밀번호를 잠금해제하시겠습니까?")) return;
    var url = "/bns/ListSrchl.do?method=executeUserInitPassword";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_DtlInfo)";
    trs_Save.Post();
};



/********************************************** 
 * 함수명   : fn_ShowPass
 * 설명       : 비밀번호변경 팝업을 보여준다.
 ***********************************************/
scwin.fn_ShowPass = function(selObj) {
    if (scwin.vIsurCd == '') {
        $c.win.alert('발행기관을 선택 하십시오.');
        return;
    }
    scwin.fn_GetPar = fn_GetParIntegUsrId;
    $c.bns.fn_PopClearPwd(selObj);
};


/********************************************** 
 * 함수명   : fn_GetParIntegUsrId
 * 설명       : 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIntegUsrId = function(arrPar) {
    scwin.arrPar[0] = {
        ISUR_CD: $c.stf.getObjectValue(txb_IsurCdDtl),
        INTEG_USR_ID: $c.stf.getObjectValue(txb_IntegUsrId)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};


/********************************************** 
 * 함수명   : fn_openKisComCd
 * 설명       : KIS_COM_CD update 호출
 ***********************************************/
scwin.fn_openKisComCd = function() {
    if (scwin.vIsurCd == '') {
        $c.win.alert('발행기관을 선택 하십시오.');
        return;
    }
    scwin.fn_GetPar = scwin.arrPar[0] = {
        ISUR_CD: $c.stf.getObjectValue(txb_IsurCdDtl),
        KIS_COM_CD: $c.stf.getObjectValue(txb_KisComCd)
    };
    scwin.fn_GetPar = fn_GetParKisComCd;
    scwin.fn_PopUpdateKisComCd(txb_IsurCd);
};


/********************************************** 
 * 함수명   : fn_GetParKisComCd
 * 설명       : 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParKisComCd = function(arrPar) {
    scwin.arrPar[0] = {
        ISUR_CD: $c.stf.getObjectValue(txb_IsurCdDtl),
        KIS_COM_CD: $c.stf.getObjectValue(txb_KisComCd),
        FSS_UNQ_NO: $c.stf.getObjectValue(txb_FssUnqNo)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};


/********************************************** 
 * 함수명   : fn_PopUpdateKisComCd
 * 설명       : KIS_COM_CD update 호출
 ***********************************************/
scwin.fn_PopUpdateKisComCd = async function(grdObj) {
    $c.bns.fn_SetPopupPos(grdObj, 'E');
    await $c.frame.CreateDialogFrame("ULDBNS25002", "/bnslistsrchl/ULDBNS25003.gfm", "KIS_COM_CD수정", obj_left, obj_top, 455, 260, "window");
};
scwin.gform_onload = function() {
    // 패널라운드 처리	
    $c.bns.BnsPanelToGroupBox(pnl_IsurSearch);
    $c.bns.BnsPanelToGroupBox(pnl_info);

    //발행기관 검색 포커스
    $c.stf.setObjectValue(txb_IsurCd, "");
    txb_IsurCd.focus();

    //비밀번호버튼 가리기
    if (js_emp_no.substring(0, 4) != "sysm") {
        //showObj(btn_clearPwd, false);			//현업부서에 권한할당
        $c.stf.showObj(btn_clearPwd_sys, false);
        $c.stf.showObj(btn_KisComCd, false);
    }
    $c.stf.showObj(txb_KisComCd, false);
};
scwin.txb_IsurCd_onkeypress = function() {
    if (event.keyCode == 13) scwin.fn_SearchIsur();
};
scwin.cmb_BndListCorpYn_OnSelChange = function() {
    scwin.vCorpYn = $c.stf.getObjectValue(cmb_BndListCorpYn);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_SearchIsur();
};
scwin.dts_IsurList_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_IsurList_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_IsurList);
};
scwin.dts_IsurList_OnRowPosChanged = function(row) {
    if (row > 0) {
        scwin.vIsurCd = dts_IsurList.getCellData(row, "ISUR_CD");
        scwin.fn_SearchIsurDtl();
    }
    scwin.vChgYn = 'N';
};
scwin.dts_DtlInfo_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_DtlInfo_OnLoadCompleted = function(rowcount) {
    if (rowcount == 0) {
        dts_DtlInfo.removeAll();
    }

    //주권법인여부 체크 설정
    if (dts_DtlInfo.getCellData(1, "STKCERT_LIST_CORP_YN") == 'Y') {
        chk_StkcertListCorpYn.setValue(1);
    } else {
        chk_StkcertListCorpYn.setValue(0);
    }
    //채권법인여부 체크 설정
    if (dts_DtlInfo.getCellData(1, "BND_LIST_CORP_YN") == 'Y') {
        chk_BndListCorpYn.setValue(1);
    } else {
        chk_BndListCorpYn.setValue(0);
    }
    //신고담당자 정부 조회
    scwin.fn_SelectBdchrgList();
    //회사명 변경 내역 조회
    scwin.fn_ComChgList();
    scwin.vChgYn = 'N';
};
scwin.btn_ChrgMod_onclick = function() {
    scwin.processGp = '4';
    scwin.fn_Mod();
};
scwin.trs_Save_OnFail = function() {
    if (scwin.processGp == '4') {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "수정"));
    }
};
scwin.trs_Save_OnSuccess = function() {
    if (scwin.processGp == '4') {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "수정"));
        dts_DtlInfo.Reset();
    }
};
scwin.dts_DtlInfo_OnColumnChanged = function(row, colid) {
    if (colid == 'CHRG_NM' ||
        colid == 'CHRG_TEL_NO1' || colid == 'CHRG_TEL_NO2' || colid == 'CHRG_TEL_NO3' || colid == 'CHRG_INNR_NO' ||
        colid == 'CHRG_FAX_NO1' || colid == 'CHRG_FAX_NO2' || colid == 'CHRG_FAX_NO3' ||
        colid == 'ENCRYP_CHRG_EMAIL1' || colid == 'ENCRYP_CHRG_EMAIL2' ||
        colid == 'CHRG_CELLPHONE_NO1' || colid == 'CHRG_CELLPHONE_NO2' || colid == 'CHRG_CELLPHONE_NO3') {
        scwin.vChgYn = 'Y';
    }
};
scwin.btn_clearPwd_onclick = function() {
    scwin.processGp = '4';
    scwin.fn_clearPwd();
};
scwin.btn_clearPwd_sys_onclick = function() {
    scwin.processGp = '4';
    scwin.fn_ShowPass(txb_IsurCd);
};
scwin.dts_pwd_OnLoadCompleted = function(rowcount) {

};
scwin.btn_KisComCd_onclick = function() {
    scwin.fn_openKisComCd();
};
